#!/usr/bin/env node
import {readFile,writeFile,mkdir,copyFile,access} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
const payload={"component": "import React, {useEffect,useRef,useState} from 'react';\nimport './MusicPlayer.css';\nconst format=(value)=>{const n=Number.isFinite(value)?Math.floor(value):0;return Math.floor(n/60)+':'+String(n%60).padStart(2,'0')};\nexport default function MusicPlayer(){\n const audio=useRef(null);\n const [playing,setPlaying]=useState(false),[open,setOpen]=useState(true),[volume,setVolume]=useState(()=>{try{const v=localStorage.getItem('studybuddy-music-volume');return v===null?.35:Math.max(0,Math.min(1,Number(v)||0))}catch{return .35}}),[current,setCurrent]=useState(0),[duration,setDuration]=useState(0),[error,setError]=useState('');\n useEffect(()=>{if(audio.current)audio.current.volume=volume;try{localStorage.setItem('studybuddy-music-volume',String(volume))}catch{}},[volume]);\n async function toggle(){const a=audio.current;if(!a)return;if(!a.paused){a.pause();return}setError('');try{await a.play()}catch{setError('Chưa phát được nhạc. Hãy thử lại hoặc kiểm tra tệp âm thanh.')}}\n function stop(){if(audio.current){audio.current.pause();audio.current.currentTime=0;setCurrent(0)}}\n return <section className=\"sb-music\" aria-label=\"Trình phát nhạc\"><audio ref={audio} src={import.meta.env.BASE_URL+'audio/khuc-ca-doi-minh.mp3'} preload=\"metadata\" onPlay={()=>setPlaying(true)} onPause={()=>setPlaying(false)} onEnded={()=>setPlaying(false)} onLoadedMetadata={()=>setDuration(audio.current.duration)} onTimeUpdate={()=>setCurrent(audio.current.currentTime)} onError={()=>{setPlaying(false);setError('Không tải được bài nhạc. Vui lòng kiểm tra kết nối.')}}/>\n <div className=\"sb-music-heading\"><span>♫ Khúc Ca Đôi Mình</span><button type=\"button\" aria-expanded={open} aria-label={open?'Thu gọn trình phát':'Mở trình phát'} onClick={()=>setOpen(!open)}>{open?'−':'+'}</button></div>\n {open&&<><div className=\"sb-music-buttons\"><button type=\"button\" onClick={toggle} aria-label={playing?'Tạm dừng nhạc':'Phát nhạc'}>{playing?'❚❚ Tạm dừng':'▶ Phát nhạc'}</button><button type=\"button\" onClick={stop}>■ Dừng</button><span className=\"sb-music-time\">{format(current)} / {format(duration)}</span></div>\n <label className=\"sb-music-seek\">Vị trí bài nhạc<input aria-label=\"Vị trí bài nhạc\" type=\"range\" min=\"0\" max={duration||0} step=\".1\" value={Math.min(current,duration||0)} disabled={!duration} onChange={e=>{const n=Number(e.target.value);audio.current.currentTime=n;setCurrent(n)}}/></label>\n <div className=\"sb-music-volume\"><button type=\"button\" aria-label=\"Giảm âm lượng\" onClick={()=>setVolume(v=>Math.max(0,v-.1))}>−</button><label>Âm lượng<input aria-label=\"Âm lượng\" type=\"range\" min=\"0\" max=\"1\" step=\".01\" value={volume} onChange={e=>setVolume(Number(e.target.value))}/></label><button type=\"button\" aria-label=\"Tăng âm lượng\" onClick={()=>setVolume(v=>Math.min(1,v+.1))}>+</button><span>{Math.round(volume*100)}%</span></div></>}\n {error&&<p role=\"status\" className=\"sb-music-error\">{error}</p>}\n </section>;\n}\n", "css": ".sb-music{position:fixed;bottom:16px;right:16px;z-index:1000;width:340px;max-width:calc(100vw - 24px);padding:14px;border:1px solid #dcdcf1;border-radius:18px;background:rgba(255,255,255,.98);color:#25254b;box-shadow:0 8px 32px #28255a26;font:13px/1.5 Inter,system-ui,sans-serif}.sb-music *{box-sizing:border-box}.sb-music-heading{display:flex;justify-content:space-between;align-items:center;font-weight:700;gap:8px}.sb-music button{border:1px solid #dfdff0;border-radius:9px;background:#f3f2ff;color:#4648d4;padding:6px 10px;cursor:pointer;white-space:nowrap;font:inherit}.sb-music button:focus-visible,.sb-music input:focus-visible{outline:2px solid #4648d4;outline-offset:2px}.sb-music-buttons{display:flex;align-items:center;gap:8px;margin-top:12px}.sb-music-time{font-size:11px;margin-left:auto;font-variant-numeric:tabular-nums}.sb-music-seek{display:block;font-size:11px;margin:10px 0}.sb-music-seek input{display:block;width:100%}.sb-music input[type=range]{accent-color:#4648d4;cursor:pointer;min-width:0}.sb-music-volume{display:flex;align-items:center;gap:8px}.sb-music-volume label{flex:1;min-width:0;font-size:11px}.sb-music-volume input{display:block;width:100%}.sb-music-volume>span{min-width:32px;text-align:right;font-size:11px}.sb-music-error{margin-top:8px;color:#b42318;font-size:12px}@media(max-width:480px){.sb-music{bottom:10px;right:12px;width:310px;padding:12px}}@media print{.sb-music{display:none}}\n", "audio": "", "sha256": "ad7e2083335022e54e589530f30147b227ccd712d473522f3691a9b17fe00597"};

async function exists(p){try{await access(p);return true}catch{return false}}
async function main(){
 const args=process.argv.slice(2),explicit=args.find(x=>!x.startsWith('--'));
 const here=path.dirname(fileURLToPath(import.meta.url));
 const candidates=explicit?[path.resolve(explicit)]:[process.cwd(),here,path.join(process.cwd(),'studybuddy-react'),path.join(here,'studybuddy-react'),path.dirname(here)];
 let root;
 for(const dir of candidates)if(await exists(path.join(dir,'package.json'))&&await exists(path.join(dir,'src/main.jsx'))){root=dir;break}
 if(!root)throw new Error('Khong tim thay du an. Dat file .mjs cung package.json, hoac chay: node update-studybuddy-music.mjs "DUONG_DAN_DU_AN"');
 const audio=Buffer.from(payload.audio,'base64');
 if(createHash('sha256').update(audio).digest('hex')!==payload.sha256)throw new Error('Du lieu nhac khong toan ven. Hay giai nen lai file cap nhat.');
 const entry=path.join(root,'src/main.jsx');let main=await readFile(entry,'utf8');
 const marker='// studybuddy-music-update-v1';
 if(!main.includes(marker)){
  if(main.includes('MusicPlayer'))throw new Error('Du an da co MusicPlayer khac. Dung lai de tranh ghi de nham.');
  if(!main.includes('.render(<HashRouter>')||!main.includes('</HashRouter>);'))throw new Error('Cau truc src/main.jsx khac ban da cung cap. Chua thay doi tep nao.');
  main=marker+"\nimport MusicPlayer from './components/MusicPlayer';\n"+main.replace('.render(<HashRouter>','.render(<><MusicPlayer /><HashRouter>').replace('</HashRouter>);','</HashRouter></>);');
 }
 const writes=[['src/main.jsx',main],['src/components/MusicPlayer.jsx',payload.component],['src/components/MusicPlayer.css',payload.css],['public/audio/khuc-ca-doi-minh.mp3',audio]];
 // Also retain compatibility with the original React-import fix.
 for(const name of ['Home','Flashcards','Quiz','Chat']){
  const relative='src/pages/'+name+'.jsx',file=path.join(root,relative);
  if(!(await exists(file)))continue;
  const text=await readFile(file,'utf8');
  const fixed=text.replace(/import\s*\{\s*useEffect\s*,\s*useRef\s*\}\s*from\s*(['"])react\1\s*;/,"import React, {useEffect,useRef} from 'react';");
  if(text!==fixed)writes.push([relative,fixed]);
 }
 const changed=[];
 for(const [relative,data] of writes){const file=path.join(root,relative);const bytes=Buffer.isBuffer(data)?data:Buffer.from(data);if(await exists(file)){const previous=await readFile(file);if(previous.equals(bytes))continue}changed.push([relative,bytes]);}
 if(changed.length){
  const backup=path.join(root,'.studybuddy-backups','music-'+new Date().toISOString().replace(/[:.]/g,'-'));
  await mkdir(backup,{recursive:true});const manifest=[];
  for(const [relative] of changed){const file=path.join(root,relative),existed=await exists(file);manifest.push({path:relative,existed});if(existed){const dest=path.join(backup,relative);await mkdir(path.dirname(dest),{recursive:true});await copyFile(file,dest)}}
  await writeFile(path.join(backup,'manifest.json'),JSON.stringify(manifest,null,2));
  for(const [relative,bytes] of changed){const file=path.join(root,relative);await mkdir(path.dirname(file),{recursive:true});await writeFile(file,bytes);console.log('[UPDATED] '+relative)}
  console.log('Ban sao luu: '+backup);
 }else console.log('Ban nhac da duoc cap nhat. Khong thay doi tep.');
 if(args.includes('--no-build')){console.log('Hoan tat cap nhat. Chay npm run build khi can.');return}
 if(!(await exists(path.join(root,'node_modules/vite/package.json')))){console.log('Da cap nhat. Hay chay npm install, sau do npm run build.');return}
 const result=spawnSync(process.platform==='win32'?'npm.cmd':'npm',['run','build'],{cwd:root,stdio:'inherit',shell:process.platform==='win32'});
 if(result.error)throw result.error;
 if(result.status!==0)throw new Error('Da cap nhat nhac nhung build chua thanh cong. Xem loi ben tren.');
 console.log('HOAN TAT. Chay npm run dev; neu dung hosting, upload lai noi dung dist. Nhan Phat nhac de nghe.');
}
main().catch(error=>{console.error('LOI: '+error.message);process.exitCode=1});
